    code: "import React, { useState, useEffect, useRef, useCallback } from 'react';\nimport { Play, RotateCcw, Volume2, VolumeX, BarChart2, Zap, ArrowDownUp } from 'lucide-react';\n\nexport default function SortingVisualizer() {\n  const [array, setArray] = useState([]);\n  const [arraySize, setArraySize] = useState(30);\n  const [speed, setSpeed] = useState(25);\n  const [algorithm, setAlgorithm] = useState('quicksort');\n  const [isSorting, setIsSorting] = useState(false);\n  const [comparisons, setComparisons] = useState(0);\n  const [swaps, setSwaps] = useState(0);\n  const [comparing, setComparing] = useState([]);\n  const [sortedIndices, setSortedIndices] = useState(new Set());\n  const [soundEnabled, setSoundEnabled] = useState(true);\n\n  const abortRef = useRef(false);\n  const arrayRef = useRef([]);\n\n  const resetArray = useCallback(() => {\n    abortRef.current = true;\n    setIsSorting(false);\n    setComparisons(0);\n    setSwaps(0);\n    setComparing([]);\n    setSortedIndices(new Set());\n\n    const newArr = [];\n    for (let i = 0; i < arraySize; i++) {\n      newArr.push(Math.floor(Math.random() * 88) + 12);\n    }\n    setArray(newArr);\n    arrayRef.current = newArr;\n  }, [arraySize]);\n\n  useEffect(() => {\n    resetArray();\n  }, [resetArray]);\n\n  const playTone = useCallback((val) => {\n    if (!soundEnabled) return;\n    try {\n      const AudioCtx = window.AudioContext || window.webkitAudioContext;\n      if (!AudioCtx) return;\n      const ctx = new AudioCtx();\n      const osc = ctx.createOscillator();\n      const gain = ctx.createGain();\n      osc.type = 'triangle';\n      osc.frequency.setValueAtTime(180 + val * 8, ctx.currentTime);\n      gain.gain.setValueAtTime(0.04, ctx.currentTime);\n      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);\n      osc.connect(gain);\n      gain.connect(ctx.destination);\n      osc.start();\n      osc.stop(ctx.currentTime + 0.05);\n    } catch (_) {}\n  }, [soundEnabled]);\n\n  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n\n  // Quick Sort\n  const runQuickSort = async () => {\n    abortRef.current = false;\n    setIsSorting(true);\n    let compCount = 0;\n    let swapCount = 0;\n    const arr = [...arrayRef.current];\n\n    const partition = async (low, high) => {\n      const pivot = arr[high];\n      let i = low - 1;\n\n      for (let j = low; j < high; j++) {\n        if (abortRef.current) return -1;\n        setComparing([j, high]);\n        compCount++;\n        setComparisons(compCount);\n        playTone(arr[j]);\n        await sleep(speed);\n\n        if (arr[j] < pivot) {\n          i++;\n          const tmp = arr[i];\n          arr[i] = arr[j];\n          arr[j] = tmp;\n          swapCount++;\n          setSwaps(swapCount);\n          setArray([...arr]);\n        }\n      }\n\n      const tmp = arr[i + 1];\n      arr[i + 1] = arr[high];\n      arr[high] = tmp;\n      swapCount++;\n      setSwaps(swapCount);\n      setArray([...arr]);\n      return i + 1;\n    };\n\n    const quickSort = async (low, high) => {\n      if (low < high && !abortRef.current) {\n        const pi = await partition(low, high);\n        if (pi === -1) return;\n        setSortedIndices(prev => new Set([...prev, pi]));\n        await quickSort(low, pi - 1);\n        await quickSort(pi + 1, high);\n      } else if (low === high) {\n        setSortedIndices(prev => new Set([...prev, low]));\n      }\n    };\n\n    await quickSort(0, arr.length - 1);\n    if (!abortRef.current) {\n      setSortedIndices(new Set(arr.map((_, idx) => idx)));\n    }\n    setComparing([]);\n    setIsSorting(false);\n  };\n\n  // Bubble Sort\n  const runBubbleSort = async () => {\n    abortRef.current = false;\n    setIsSorting(true);\n    let compCount = 0;\n    let swapCount = 0;\n    const arr = [...arrayRef.current];\n    const n = arr.length;\n\n    for (let i = 0; i < n - 1; i++) {\n      for (let j = 0; j < n - i - 1; j++) {\n        if (abortRef.current) return;\n        setComparing([j, j + 1]);\n        compCount++;\n        setComparisons(compCount);\n        playTone(arr[j]);\n        await sleep(speed);\n\n        if (arr[j] > arr[j + 1]) {\n          const tmp = arr[j];\n          arr[j] = arr[j + 1];\n          arr[j + 1] = tmp;\n          swapCount++;\n          setSwaps(swapCount);\n          setArray([...arr]);\n        }\n      }\n      setSortedIndices(prev => new Set([...prev, n - i - 1]));\n    }\n    setSortedIndices(new Set(arr.map((_, idx) => idx)));\n    setComparing([]);\n    setIsSorting(false);\n  };\n\n  // Insertion Sort\n  const runInsertionSort = async () => {\n    abortRef.current = false;\n    setIsSorting(true);\n    let compCount = 0;\n    let swapCount = 0;\n    const arr = [...arrayRef.current];\n    const n = arr.length;\n\n    for (let i = 1; i < n; i++) {\n      let key = arr[i];\n      let j = i - 1;\n\n      while (j >= 0 && arr[j] > key) {\n        if (abortRef.current) return;\n        setComparing([j, j + 1]);\n        compCount++;\n        setComparisons(compCount);\n        playTone(arr[j]);\n        await sleep(speed);\n\n        arr[j + 1] = arr[j];\n        swapCount++;\n        setSwaps(swapCount);\n        setArray([...arr]);\n        j--;\n      }\n      arr[j + 1] = key;\n      setArray([...arr]);\n      setSortedIndices(prev => new Set([...prev, i]));\n    }\n    setSortedIndices(new Set(arr.map((_, idx) => idx)));\n    setComparing([]);\n    setIsSorting(false);\n  };\n\n  const handleStartSort = () => {\n    if (isSorting) return;\n    setSortedIndices(new Set());\n    if (algorithm === 'quicksort') runQuickSort();\n    else if (algorithm === 'bubblesort') runBubbleSort();\n    else if (algorithm === 'insertionsort') runInsertionSort();\n  };\n\n  return (\n    <div className=\"w-full max-w-4xl mx-auto p-5 bg-[#080B15] text-white rounded-3xl border border-cyan-500/30 shadow-2xl space-y-5 font-sans\">\n      {/* Header */}\n      <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-white/10 pb-4\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"p-2.5 rounded-2xl bg-cyan-500/20 text-cyan-400 border border-cyan-500/30\">\n            <ArrowDownUp className=\"w-6 h-6\" />\n          </div>\n          <div>\n            <h2 className=\"text-lg font-bold text-white flex items-center gap-2\">\n              Advanced Sorting Visualizer\n              <span className=\"px-2 py-0.5 rounded-md bg-cyan-500/10 text-cyan-300 font-mono text-[10px] border border-cyan-500/30\">\n                {algorithm === 'quicksort' ? 'O(n log n)' : 'O(n²)'}\n              </span>\n            </h2>\n            <p className=\"text-xs text-gray-400 font-mono\">Real-time Comparative Array Transformation Engine</p>\n          </div>\n        </div>\n\n        {/* Telemetry Stats */}\n        <div className=\"flex items-center gap-3 font-mono text-xs\">\n          <div className=\"px-3 py-1.5 rounded-xl bg-white/5 border border-white/10\">\n            <span className=\"text-gray-400 text-[10px] block\">COMPARISONS</span>\n            <span className=\"text-cyan-400 font-bold\">{comparisons.toLocaleString()}</span>\n          </div>\n          <div className=\"px-3 py-1.5 rounded-xl bg-white/5 border border-white/10\">\n            <span className=\"text-gray-400 text-[10px] block\">ARRAY SWAPS</span>\n            <span className=\"text-emerald-400 font-bold\">{swaps.toLocaleString()}</span>\n          </div>\n        </div>\n      </div>\n\n      {/* Control Bar */}\n      <div className=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3 bg-black/40 p-3 rounded-2xl border border-white/5 text-xs font-mono\">\n        <div className=\"space-y-1\">\n          <label className=\"text-gray-400 text-[10px]\">ALGORITHM</label>\n          <select\n            value={algorithm}\n            onChange={(e) => setAlgorithm(e.target.value)}\n            disabled={isSorting}\n            className=\"w-full bg-[#0E1325] border border-white/10 rounded-xl px-2.5 py-1.5 text-white focus:outline-none focus:border-cyan-400\"\n          >\n            <option value=\"quicksort\">Quick Sort (Divide & Conquer)</option>\n            <option value=\"bubblesort\">Bubble Sort (Iterative Exchange)</option>\n            <option value=\"insertionsort\">Insertion Sort (Incremental Build)</option>\n          </select>\n        </div>\n\n        <div className=\"space-y-1\">\n          <div className=\"flex justify-between text-gray-400 text-[10px]\">\n            <span>ARRAY SIZE: {arraySize}</span>\n          </div>\n          <input\n            type=\"range\"\n            min=\"15\"\n            max=\"60\"\n            value={arraySize}\n            onChange={(e) => setArraySize(Number(e.target.value))}\n            disabled={isSorting}\n            className=\"w-full accent-cyan-400 cursor-pointer\"\n          />\n        </div>\n\n        <div className=\"space-y-1\">\n          <div className=\"flex justify-between text-gray-400 text-[10px]\">\n            <span>SPEED: {speed}ms</span>\n          </div>\n          <input\n            type=\"range\"\n            min=\"5\"\n            max=\"80\"\n            value={speed}\n            onChange={(e) => setSpeed(Number(e.target.value))}\n            className=\"w-full accent-purple-400 cursor-pointer\"\n          />\n        </div>\n\n        <div className=\"flex items-end gap-2\">\n          <button\n            onClick={resetArray}\n            disabled={isSorting}\n            className=\"flex-1 py-2 rounded-xl bg-white/5 hover:bg-white/10 text-gray-300 font-bold border border-white/10 transition-all flex items-center justify-center gap-1 cursor-pointer disabled:opacity-50\"\n          >\n            <RotateCcw className=\"w-3.5 h-3.5\" /> Reset\n          </button>\n          <button\n            onClick={() => setSoundEnabled(!soundEnabled)}\n            className={\"p-2 rounded-xl border transition-all cursor-pointer \" + (soundEnabled ? 'bg-cyan-500/20 border-cyan-500/30 text-cyan-400' : 'bg-white/5 border-white/10 text-gray-500')}\n            title=\"Toggle Audio Pitch Feedback\"\n          >\n            {soundEnabled ? <Volume2 className=\"w-4 h-4\" /> : <VolumeX className=\"w-4 h-4\" />}\n          </button>\n          <button\n            onClick={handleStartSort}\n            disabled={isSorting}\n            className=\"flex-1 py-2 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-400 hover:to-blue-500 text-black font-extrabold shadow-lg shadow-cyan-500/20 transition-all flex items-center justify-center gap-1 cursor-pointer disabled:opacity-50\"\n          >\n            <Play className=\"w-3.5 h-3.5 fill-current\" /> Sort\n          </button>\n        </div>\n      </div>\n\n      {/* Visualizer Display Bars */}\n      <div className=\"h-64 bg-[#05070F] rounded-2xl p-4 border border-white/10 flex items-end justify-center gap-1 sm:gap-1.5 shadow-inner relative overflow-hidden\">\n        {array.map((val, idx) => {\n          const isComp = comparing.includes(idx);\n          const isSorted = sortedIndices.has(idx);\n\n          let barColor = 'bg-cyan-500/80';\n          let shadow = 'shadow-[0_0_8px_rgba(6,182,212,0.4)]';\n\n          if (isComp) {\n            barColor = 'bg-rose-500';\n            shadow = 'shadow-[0_0_14px_rgba(244,63,94,0.8)]';\n          } else if (isSorted) {\n            barColor = 'bg-emerald-400';\n            shadow = 'shadow-[0_0_8px_rgba(52,211,153,0.5)]';\n          }\n\n          return (\n            <div\n              key={idx}\n              className={\"flex-1 rounded-t-md transition-all \" + barColor + \" \" + shadow}\n              style={{ height: val + '%' }}\n            />\n          );\n        })}\n      </div>\n\n      {/* Legend & Complexity Footer */}\n      <div className=\"flex flex-wrap items-center justify-between gap-3 text-xs font-mono text-gray-400 pt-1\">\n        <div className=\"flex items-center gap-4\">\n          <div className=\"flex items-center gap-1.5\">\n            <span className=\"w-2.5 h-2.5 rounded-full bg-cyan-500\"></span> Unsorted\n          </div>\n          <div className=\"flex items-center gap-1.5\">\n            <span className=\"w-2.5 h-2.5 rounded-full bg-rose-500\"></span> Active Compare\n          </div>\n          <div className=\"flex items-center gap-1.5\">\n            <span className=\"w-2.5 h-2.5 rounded-full bg-emerald-400\"></span> In Sorted Position\n          </div>\n        </div>\n        <div className=\"text-[11px] text-gray-500\">\n          Synthesized in pure React 18 • Web Audio Tone Pitch Active\n        </div>\n      </div>\n    </div>\n  );\n}"
