    keywords: ['crypto', 'trading', 'terminal', 'candlestick', 'stock chart', 'order book', 'bitcoin', 'btc'],
    code: "import React, { useState, useEffect } from 'react';\nimport { TrendingUp, TrendingDown, ArrowUpRight, ArrowDownRight, DollarSign, Activity, RefreshCw } from 'lucide-react';\n\nexport default function CryptoTradingTerminal() {\n  const [ticker, setTicker] = useState('BTC/USDT');\n  const [price, setPrice] = useState(68450.00);\n  const [priceChange, setPriceChange] = useState(+3.42);\n  const [candles, setCandles] = useState([\n    { open: 66800, close: 67200, high: 67400, low: 66600 },\n    { open: 67200, close: 67100, high: 67500, low: 66900 },\n    { open: 67100, close: 67800, high: 68100, low: 67000 },\n    { open: 67800, close: 67600, high: 67900, low: 67400 },\n    { open: 67600, close: 68200, high: 68400, low: 67500 },\n    { open: 68200, close: 68450, high: 68900, low: 68100 }\n  ]);\n  const [balance, setBalance] = useState(100000);\n  const [position, setPosition] = useState(null); // { type: 'LONG'|'SHORT', entryPrice, amount }\n  const [orderAmount, setOrderAmount] = useState(0.5);\n\n  // Live Simulated Price Ticks\n  useEffect(() => {\n    const timer = setInterval(() => {\n      setPrice(prev => {\n        const delta = (Math.random() - 0.48) * 45;\n        const next = Math.round((prev + delta) * 100) / 100;\n        return next;\n      });\n    }, 1200);\n    return () => clearInterval(timer);\n  }, []);\n\n  const handleBuy = () => {\n    const cost = orderAmount * price;\n    if (cost > balance) return;\n    setBalance(b => b - cost);\n    setPosition({ type: 'LONG', entryPrice: price, amount: orderAmount });\n  };\n\n  const handleSell = () => {\n    if (!position) return;\n    const returnVal = position.amount * price;\n    setBalance(b => b + returnVal);\n    setPosition(null);\n  };\n\n  const unrealizedPnL = position \n    ? (price - position.entryPrice) * position.amount * (position.type === 'LONG' ? 1 : -1)\n    : 0;\n\n  return (\n    <div className=\"w-full max-w-4xl mx-auto p-5 bg-[#080B15] text-white rounded-3xl border border-cyan-500/30 shadow-2xl space-y-4 font-sans\">\n      {/* Header */}\n      <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-white/10 pb-4\">\n        <div className=\"flex items-center gap-3\">\n          <div className=\"p-2.5 rounded-2xl bg-cyan-500/20 text-cyan-400 border border-cyan-500/30\">\n            <Activity className=\"w-6 h-6\" />\n          </div>\n          <div>\n            <div className=\"flex items-center gap-2\">\n              <h2 className=\"text-lg font-bold text-white font-mono\">{ticker}</h2>\n              <span className={\"px-2 py-0.5 rounded text-[10px] font-mono font-bold \" + (priceChange >= 0 ? 'bg-emerald-500/20 text-emerald-300' : 'bg-rose-500/20 text-rose-300')}>\n                {priceChange >= 0 ? '+' : ''}{priceChange}%\n              </span>\n            </div>\n            <div className=\"text-2xl font-black font-mono tracking-tight text-white mt-0.5\">\n              {\"$\"}{price.toLocaleString(undefined, { minimumFractionDigits: 2 })}\n            </div>\n          </div>\n        </div>\n\n        {/* Portfolio Stats */}\n        <div className=\"flex items-center gap-3 font-mono text-xs\">\n          <div className=\"px-3 py-2 rounded-xl bg-white/5 border border-white/10 text-right\">\n            <span className=\"text-gray-400 text-[10px] block\">DEMO CAPITAL</span>\n            <span className=\"text-cyan-400 font-bold\">{\"$\"}{balance.toLocaleString(undefined, { maximumFractionDigits: 2 })}</span>\n          </div>\n          <div className=\"px-3 py-2 rounded-xl bg-white/5 border border-white/10 text-right\">\n            <span className=\"text-gray-400 text-[10px] block\">UNREALIZED P&L</span>\n            <span className={\"font-bold \" + (unrealizedPnL >= 0 ? 'text-emerald-400' : 'text-rose-400')}>\n              {unrealizedPnL >= 0 ? '+$' : '-$'}{Math.abs(unrealizedPnL).toFixed(2)}\n            </span>\n          </div>\n        </div>\n      </div>\n\n      {/* Candlestick & Order Book Grid */}\n      <div className=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n        {/* Candlestick Chart (2 cols) */}\n        <div className=\"md:col-span-2 bg-[#05070F] p-4 rounded-2xl border border-white/10 flex flex-col justify-between h-64\">\n          <div className=\"flex items-center justify-between text-xs font-mono text-gray-400\">\n            <span>Price Action (15M Candles)</span>\n            <span className=\"text-cyan-400\">EMA 20 Active</span>\n          </div>\n\n          <div className=\"flex-1 flex items-end justify-between gap-3 py-4\">\n            {candles.map((c, i) => {\n              const isUp = c.close >= c.open;\n              const height = Math.abs(c.close - c.open) / 25 + 20;\n              return (\n                <div key={i} className=\"flex-1 flex flex-col items-center justify-end h-full relative\">\n                  <div className={\"w-0.5 h-full absolute \" + (isUp ? 'bg-emerald-500/40' : 'bg-rose-500/40')} />\n                  <div\n                    className={\"w-full rounded-sm z-10 \" + (isUp ? 'bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.5)]' : 'bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.5)]')}\n                    style={{ height: height + 'px' }}\n                  />\n                </div>\n              );\n            })}\n          </div>\n\n          <div className=\"flex justify-between text-[10px] font-mono text-gray-500 border-t border-white/5 pt-2\">\n            <span>12:00</span>\n            <span>12:30</span>\n            <span>13:00</span>\n            <span>13:30</span>\n            <span>14:00</span>\n            <span>LIVE NOW</span>\n          </div>\n        </div>\n\n        {/* Order Book & Desk (1 col) */}\n        <div className=\"bg-[#05070F] p-4 rounded-2xl border border-white/10 flex flex-col justify-between font-mono text-xs space-y-3\">\n          <div className=\"text-gray-400 text-[10px] font-bold\">LIVE ORDER DESK</div>\n\n          <div className=\"space-y-1.5\">\n            <div className=\"text-[10px] text-gray-400\">ORDER SIZE ({ticker.split('/')[0]})</div>\n            <div className=\"flex items-center gap-2\">\n              <input\n                type=\"number\"\n                step=\"0.1\"\n                value={orderAmount}\n                onChange={(e) => setOrderAmount(Math.max(0.01, parseFloat(e.target.value) || 0.1))}\n                className=\"w-full px-2.5 py-1.5 rounded-lg bg-black/60 border border-white/10 text-white font-mono\"\n              />\n            </div>\n          </div>\n\n          <div className=\"space-y-2 pt-2\">\n            {!position ? (\n              <button\n                onClick={handleBuy}\n                className=\"w-full py-2.5 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-black font-extrabold text-xs cursor-pointer shadow-lg shadow-emerald-500/20 active:scale-95 transition-all\"\n              >\n                Buy / Long ({orderAmount} BTC)\n              </button>\n            ) : (\n              <button\n                onClick={handleSell}\n                className=\"w-full py-2.5 rounded-xl bg-rose-500 hover:bg-rose-400 text-white font-extrabold text-xs cursor-pointer shadow-lg shadow-rose-500/20 active:scale-95 transition-all\"\n              >\n                Close Position (Sell)\n              </button>\n            )}\n          </div>\n\n          <div className=\"p-2.5 rounded-xl bg-white/[0.02] border border-white/5 text-[10px] space-y-1 text-gray-400\">\n            <div className=\"flex justify-between\">\n              <span>Spread</span>\n              <span className=\"text-white\">$0.05</span>\n            </div>\n            <div className=\"flex justify-between\">\n              <span>Maker Fee</span>\n              <span className=\"text-emerald-400\">0.00%</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}"
