    keywords: ['perceptron', 'neural network', 'decision boundary', 'machine learning', 'linear classifier', 'ai model'],
    code: "import React, { useState, useEffect, useRef } from 'react';\nimport { Brain, Play, RotateCcw, PlusCircle, RefreshCw } from 'lucide-react';\n\nexport default function NeuralPerceptron() {\n  const canvasRef = useRef(null);\n  const [points, setPoints] = useState([\n    { x: -0.6, y: -0.5, label: 0 },\n    { x: -0.4, y: -0.2, label: 0 },\n    { x: -0.7, y: 0.1, label: 0 },\n    { x: 0.5, y: 0.6, label: 1 },\n    { x: 0.7, y: 0.3, label: 1 },\n    { x: 0.3, y: 0.8, label: 1 }\n  ]);\n  const [weights, setWeights] = useState({ w1: 0.2, w2: -0.3, b: 0.1 });\n  const [activeClass, setActiveClass] = useState(0);\n  const [epochs, setEpochs] = useState(0);\n  const [accuracy, setAccuracy] = useState(100);\n\n  const trainEpoch = () => {\n    let { w1, w2, b } = weights;\n    const lr = 0.08;\n    let correct = 0;\n\n    points.forEach(p => {\n      const z = w1 * p.x + w2 * p.y + b;\n      const pred = z >= 0 ? 1 : 0;\n      const err = p.label - pred;\n\n      if (pred === p.label) correct++;\n\n      w1 += lr * err * p.x;\n      w2 += lr * err * p.y;\n      b += lr * err;\n    });\n\n    setWeights({ w1, w2, b });\n    setEpochs(e => e + 1);\n    setAccuracy(Math.round((correct / (points.length || 1)) * 100));\n  };\n\n  const handleCanvasClick = (e) => {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const rect = canvas.getBoundingClientRect();\n    const px = ((e.clientX - rect.left) / canvas.width) * 2 - 1;\n    const py = -(((e.clientY - rect.top) / canvas.height) * 2 - 1);\n\n    setPoints(prev => [...prev, { x: px, y: py, label: activeClass }]);\n  };\n\n  // Render canvas\n  useEffect(() => {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n\n    ctx.fillStyle = '#060814';\n    ctx.fillRect(0, 0, w, h);\n\n    // Grid lines\n    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';\n    ctx.lineWidth = 1;\n    ctx.beginPath();\n    ctx.moveTo(w / 2, 0); ctx.lineTo(w / 2, h);\n    ctx.moveTo(0, h / 2); ctx.lineTo(w, h / 2);\n    ctx.stroke();\n\n    // Draw Decision Boundary: w1*x + w2*y + b = 0 => y = (-w1*x - b)/w2\n    if (Math.abs(weights.w2) > 0.001) {\n      const x1 = -1;\n      const y1 = (-weights.w1 * x1 - weights.b) / weights.w2;\n      const x2 = 1;\n      const y2 = (-weights.w1 * x2 - weights.b) / weights.w2;\n\n      const sx1 = ((x1 + 1) / 2) * w;\n      const sy1 = ((-y1 + 1) / 2) * h;\n      const sx2 = ((x2 + 1) / 2) * w;\n      const sy2 = ((-y2 + 1) / 2) * h;\n\n      ctx.save();\n      ctx.strokeStyle = '#00F0FF';\n      ctx.lineWidth = 2.5;\n      ctx.shadowBlur = 10;\n      ctx.shadowColor = '#00F0FF';\n      ctx.beginPath();\n      ctx.moveTo(sx1, sy1);\n      ctx.lineTo(sx2, sy2);\n      ctx.stroke();\n      ctx.restore();\n    }\n\n    // Draw Data Points\n    points.forEach(p => {\n      const cx = ((p.x + 1) / 2) * w;\n      const cy = ((-p.y + 1) / 2) * h;\n\n      ctx.save();\n      ctx.fillStyle = p.label === 0 ? '#00F0FF' : '#EC4899';\n      ctx.shadowBlur = 8;\n      ctx.shadowColor = ctx.fillStyle;\n      ctx.beginPath();\n      ctx.arc(cx, cy, 6, 0, Math.PI * 2);\n      ctx.fill();\n      ctx.restore();\n    });\n  }, [points, weights]);\n\n  return (\n    <div className=\"w-full max-w-2xl mx-auto p-5 bg-[#080B15] text-white rounded-3xl border border-cyan-500/30 shadow-2xl space-y-4 font-sans\">\n      <div className=\"flex items-center justify-between border-b border-white/10 pb-3\">\n        <div className=\"flex items-center gap-2.5\">\n          <div className=\"p-2.5 rounded-2xl bg-cyan-500/20 text-cyan-400 border border-cyan-500/30\">\n            <Brain className=\"w-6 h-6\" />\n          </div>\n          <div>\n            <h2 className=\"text-base font-bold text-white\">Neural Perceptron Visualizer</h2>\n            <p className=\"text-[10px] text-gray-400 font-mono\">Gradient Descent Linear Decision Boundary</p>\n          </div>\n        </div>\n\n        <div className=\"flex items-center gap-3 font-mono text-xs\">\n          <div>Epochs: <span className=\"text-cyan-400 font-bold\">{epochs}</span></div>\n          <div>Accuracy: <span className=\"text-emerald-400 font-bold\">{accuracy}%</span></div>\n        </div>\n      </div>\n\n      <div className=\"flex items-center justify-between gap-2 p-2.5 bg-black/40 rounded-xl border border-white/5 text-xs font-mono\">\n        <div className=\"flex items-center gap-2\">\n          <span>Add Point:</span>\n          <button\n            onClick={() => setActiveClass(0)}\n            className={\"px-3 py-1 rounded-lg border transition-all cursor-pointer \" + (activeClass === 0 ? 'bg-cyan-500 text-black font-bold border-cyan-400' : 'bg-white/5 border-white/10 text-gray-400')}\n          >\n            Class A (Cyan)\n          </button>\n          <button\n            onClick={() => setActiveClass(1)}\n            className={\"px-3 py-1 rounded-lg border transition-all cursor-pointer \" + (activeClass === 1 ? 'bg-pink-500 text-white font-bold border-pink-400' : 'bg-white/5 border-white/10 text-gray-400')}\n          >\n            Class B (Pink)\n          </button>\n        </div>\n\n        <div className=\"flex items-center gap-2\">\n          <button\n            onClick={trainEpoch}\n            className=\"px-4 py-1.5 rounded-lg bg-gradient-to-r from-cyan-500 to-blue-600 text-black font-bold cursor-pointer active:scale-95\"\n          >\n            ⚡ Train 1 Epoch\n          </button>\n        </div>\n      </div>\n\n      <div className=\"rounded-2xl overflow-hidden border border-white/10 shadow-inner bg-[#060814]\">\n        <canvas\n          ref={canvasRef}\n          width={500}\n          height={320}\n          onClick={handleCanvasClick}\n          className=\"w-full block cursor-crosshair\"\n        />\n      </div>\n    </div>\n  );\n}"
