    code: "import React, { useState, useEffect, useRef } from 'react';\nimport { ShieldCheck, Zap, AlertTriangle, Play, RefreshCw } from 'lucide-react';\n\nexport default function RateLimiterSimulator() {\n  const CAPACITY = 15;\n  const [tokens, setTokens] = useState(CAPACITY);\n  const [refillRate, setRefillRate] = useState(3); // tokens / sec\n  const [logs, setLogs] = useState([]);\n  const [totalAllowed, setTotalAllowed] = useState(0);\n  const [totalDropped, setTotalDropped] = useState(0);\n\n  // Refill tokens periodically\n  useEffect(() => {\n    const timer = setInterval(() => {\n      setTokens(prev => Math.min(CAPACITY, prev + 1));\n    }, 1000 / refillRate);\n    return () => clearInterval(timer);\n  }, [refillRate]);\n\n  const sendRequest = (count = 1) => {\n    let allowed = 0;\n    let dropped = 0;\n\n    setTokens(currTokens => {\n      let remaining = currTokens;\n      const newLogs = [];\n\n      for (let i = 0; i < count; i++) {\n        if (remaining >= 1) {\n          remaining -= 1;\n          allowed++;\n          newLogs.unshift({ status: 200, time: new Date().toLocaleTimeString() });\n        } else {\n          dropped++;\n          newLogs.unshift({ status: 429, time: new Date().toLocaleTimeString() });\n        }\n      }\n\n      setTotalAllowed(a => a + allowed);\n      setTotalDropped(d => d + dropped);\n      setLogs(prev => [...newLogs, ...prev.slice(0, 18)]);\n      return remaining;\n    });\n  };\n\n  return (\n    <div className=\"w-full max-w-2xl mx-auto p-5 bg-[#080B15] text-white rounded-3xl border border-cyan-500/30 shadow-2xl space-y-4 font-sans\">\n      <div className=\"flex items-center justify-between border-b border-white/10 pb-3\">\n        <div className=\"flex items-center gap-2.5\">\n          <div className=\"p-2.5 rounded-2xl bg-cyan-500/20 text-cyan-400 border border-cyan-500/30\">\n            <ShieldCheck className=\"w-6 h-6\" />\n          </div>\n          <div>\n            <h2 className=\"text-base font-bold text-white\">Token Bucket Rate Limiter</h2>\n            <p className=\"text-[10px] text-gray-400 font-mono\">Cloudflare & Stripe Distributed Throughput Throttler</p>\n          </div>\n        </div>\n\n        <div className=\"flex items-center gap-3 font-mono text-xs\">\n          <div className=\"text-emerald-400 font-bold\">200 OK: {totalAllowed}</div>\n          <div className=\"text-rose-400 font-bold\">429 DROPPED: {totalDropped}</div>\n        </div>\n      </div>\n\n      {/* Reservoir Tank */}\n      <div className=\"bg-black/40 p-4 rounded-2xl border border-white/10 space-y-3\">\n        <div className=\"flex justify-between text-xs font-mono\">\n          <span className=\"text-gray-400\">BUCKET CAPACITY ({tokens}/{CAPACITY} TOKENS)</span>\n          <span className=\"text-cyan-400 font-bold\">{Math.round((tokens / CAPACITY) * 100)}%</span>\n        </div>\n\n        <div className=\"w-full h-4 bg-white/10 rounded-full overflow-hidden p-0.5\">\n          <div\n            className=\"h-full bg-gradient-to-r from-cyan-500 to-blue-500 rounded-full transition-all duration-300\"\n            style={{ width: (tokens / CAPACITY * 100) + '%' }}\n          />\n        </div>\n      </div>\n\n      {/* Control Actions */}\n      <div className=\"grid grid-cols-2 gap-3\">\n        <button\n          onClick={() => sendRequest(1)}\n          className=\"py-2.5 rounded-xl bg-cyan-500 hover:bg-cyan-400 text-black font-mono font-bold text-xs cursor-pointer shadow-md\"\n        >\n          ⚡ Send 1 Request\n        </button>\n        <button\n          onClick={() => sendRequest(8)}\n          className=\"py-2.5 rounded-xl bg-purple-500 hover:bg-purple-400 text-white font-mono font-bold text-xs cursor-pointer shadow-md\"\n        >\n          💥 Traffic Burst (8 Reqs)\n        </button>\n      </div>\n\n      {/* Activity Log */}\n      <div className=\"h-36 bg-[#05070F] rounded-xl p-3 border border-white/5 overflow-y-auto space-y-1 font-mono text-xs\">\n        {logs.map((log, idx) => (\n          <div key={idx} className=\"flex items-center justify-between text-[11px]\">\n            <span className=\"text-gray-500\">{log.time}</span>\n            <span className={\"px-2 py-0.5 rounded font-bold \" + (log.status === 200 ? 'bg-emerald-500/20 text-emerald-300' : 'bg-rose-500/20 text-rose-300')}>\n              HTTP {log.status} {log.status === 200 ? 'ALLOWED' : 'RATE_LIMITED'}\n            </span>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}"
