export const matchAdvancedSkill = (prompt) => {
  if (!prompt || typeof prompt !== 'string') return null;
  const p = prompt.toLowerCase().trim();

  for (const skill of ADVANCED_SKILLS_CATALOG) {
    if (skill.keywords.some(kw => p.includes(kw))) {
      return skill;
    }
  }
  return null;
};
